        if not bad_indices:
            return 0
        freq = Counter(nums1[i] for i in bad_indices)
        max_val, max_count = freq.most_common(1)[0]
        if max_count > (len(bad_indices) + 1) // 2:
            return -1
        val_to_bad = defaultdict(list)
        for i in bad_indices:
            val_to_bad[nums1[i]].append(i)
        good_indices = [i for i in range(n) if nums1[i] != nums2[i]]
        total_cost = 0
        used = set()
        nums1_copy = nums1[:]

        # Example of using groups to find swaps
        for val, bad_inds in val_to_bad.items():
