                    nums1_copy[i], nums1_copy[j] = nums1_copy[j], nums1_copy[i]
                if not fixed:
                    # fallback: try to swap with bad indices of different value
                    for other_val, other_bad_inds in val_to_bad.items():
                        if other_val == val:
                            continue
                        for k in other_bad_inds:
                            if k in used:
